"""Responsive application frame with reversible panel controls."""
# ruff: noqa: E501


def chrome_head():
    return '<link rel="manifest" href="/portal/manifest.webmanifest"><meta name="theme-color" content="#080b0d"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="TerraSatch"><link rel="icon" href="/workspace-assets/icon.svg"><link rel="apple-touch-icon" href="/assets/satchy.png">'


def chrome_footer():
    return '''<footer class="workspace-footer"><span>TerraSatch <b>BETA</b></span><span id="network-status" role="status">Online</span><button type="button" id="toggle-nav" aria-controls="workspace-navigation" aria-expanded="true">Menu</button><button type="button" id="toggle-assistant" aria-controls="workspace-assistant" aria-expanded="true">Satchy panel</button><button type="button" id="install-workspace">Install app</button><a href="mailto:support@terrasatch.com?subject=Workspace%20beta%20feedback">Feedback</a></footer><div id="install-help" hidden role="status">Use your browser's Install app or Add to Home Screen menu. Installation availability depends on your browser.<button type="button" id="close-install-help" aria-label="Close installation help">Close</button></div>'''


def chrome_styles():
    return '''<style>
body.workspace-app{height:100dvh;overflow:hidden}.workspace-app .shell{height:100%;min-height:0}.workspace-app header{position:fixed;inset:0 0 auto;height:68px;min-height:68px;z-index:30;background:#080b0df5;box-sizing:border-box;flex-wrap:nowrap}.workspace-app main{position:fixed;inset:68px 0 46px;max-width:none;padding:18px 24px 0;display:flex;flex-direction:column;min-height:0;overflow:hidden}.workspace-app .headline{flex:none;gap:12px;margin-bottom:8px}.workspace-app .headline p{margin:5px 0}.workspace-app .workspace-beta{flex:none;margin-top:0;padding:9px 12px}.workspace-app .workspace-layout{flex:1;min-height:0;margin-top:16px;display:grid;grid-template-columns:170px minmax(0,1fr) 300px;gap:20px;overflow:hidden}.workspace-app .workspace-nav{position:static;display:flex;flex-direction:column;overflow:auto;min-height:0;align-self:stretch;margin:0;padding-bottom:18px}.workspace-app .workspace-content{min-width:0;overflow:auto;overscroll-behavior:contain;padding:0 12px 28px 0;scrollbar-gutter:stable}.workspace-app .satchy-rail{grid-column:auto;margin:0;padding:0 4px 24px 18px;border-top:0;overflow:auto;overscroll-behavior:contain;min-height:0;scrollbar-gutter:stable}.workspace-app.nav-closed .workspace-nav,.workspace-app.assistant-closed .satchy-rail{display:none}.workspace-app.nav-closed .workspace-layout{grid-template-columns:minmax(0,1fr) 300px}.workspace-app.assistant-closed .workspace-layout{grid-template-columns:170px minmax(0,1fr)}.workspace-app.nav-closed.assistant-closed .workspace-layout{grid-template-columns:minmax(0,1fr)}.panel-close{float:right;padding:5px 9px!important;width:auto!important;margin:0 0 10px auto!important;font-size:12px}.workspace-footer{position:fixed;inset:auto 0 0;min-height:46px;box-sizing:border-box;display:flex;align-items:center;gap:14px;padding:7px 20px;background:#080b0d;border-top:1px solid var(--line);z-index:40;font-size:11px}.workspace-footer b{color:#ffbd45;font-size:9px}.workspace-footer a{color:#ffbd45;margin-left:auto}.workspace-footer button{padding:5px 9px;font-size:11px}.workspace-footer #network-status{color:var(--muted)}#install-help{position:fixed;bottom:55px;right:16px;max-width:320px;background:var(--panel);border:1px solid #8e682c;border-radius:8px;padding:16px;z-index:50}#install-help button{margin-top:10px}.service-heading{display:flex;gap:12px;align-items:center}.service-icon{width:38px;height:38px;object-fit:contain;flex:none;border-radius:6px;background:#fff;padding:5px;box-sizing:border-box}.service-icon[src$="mapbox.svg"]{background:#111}.service-monogram{display:grid;place-items:center;width:38px;height:38px;border:1px solid var(--line);border-radius:6px;color:#ffbd45;font-weight:700;flex:none}.workspace-app #workspace-inbox{min-height:500px;height:100%;width:100%}.workspace-app #email{height:100%;margin:0}.workspace-app #email iframe{min-height:100%;height:100%}.optional-panel>summary{cursor:pointer;font-size:14px;font-weight:600;padding:8px 0}.workspace-app .satchy-heading{clear:both;margin-bottom:16px}.workspace-app #services-list{margin-top:12px}.workspace-app .section-heading{align-items:start}.workspace-app .section-heading h2{font-size:23px}.workspace-app .workspace-content:focus-visible{outline:2px solid #ffbd45;outline-offset:-2px}
@media(max-width:1100px){.workspace-app .workspace-layout,.workspace-app.assistant-closed .workspace-layout{grid-template-columns:145px minmax(0,1fr)}.workspace-app.nav-closed .workspace-layout{grid-template-columns:minmax(0,1fr)}.workspace-app .satchy-rail{position:fixed;right:0;top:68px;bottom:46px;width:min(380px,calc(100vw - 28px));box-sizing:border-box;padding:18px;background:#101519;border-left:1px solid #574020;z-index:25;box-shadow:-12px 0 35px #0008}.workspace-app .headline h1{font-size:20px}.workspace-app .headline{flex-direction:row;align-items:center}}
@media(max-width:700px){.workspace-app main{padding:12px 12px 0;bottom:52px}.workspace-app .headline p,.workspace-app .workspace-beta span,.workspace-app .workspace-nav p{display:none}.workspace-app .headline h1{font-size:17px}.workspace-app .organization-controls{max-width:58%;gap:5px}.workspace-app .organization-controls label{font-size:9px}.workspace-app .organization-controls select{max-width:170px;padding:6px}.workspace-app .workspace-layout,.workspace-app.assistant-closed .workspace-layout{grid-template-columns:minmax(0,1fr);gap:0;margin-top:12px}.workspace-app .workspace-nav{position:fixed;left:0;top:68px;bottom:52px;width:230px;padding:18px 12px;box-sizing:border-box;background:#101519;z-index:26;box-shadow:10px 0 30px #0008}.workspace-app .workspace-nav a{font-size:14px}.workspace-app .workspace-content{padding-right:0}.workspace-footer{min-height:52px;gap:7px;padding:7px 9px}.workspace-footer>span:first-child,.workspace-footer>a{display:none}.workspace-footer button{min-height:35px}.workspace-footer #network-status{margin-right:auto}.workspace-app .satchy-rail{bottom:52px}.workspace-app .section-heading{gap:10px}.workspace-app header .brand strong{font-size:12px}.workspace-app header .brand b{font-size:8px}.workspace-app .service-filters label{min-width:130px}}
@media(max-height:600px){.workspace-app .workspace-beta{display:none}.workspace-app .headline{margin:0}.workspace-app .headline p{display:none}.workspace-app main{padding-top:8px}.workspace-app .workspace-layout{margin-top:8px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style>'''


def chrome_script():
    return r'''<script>(()=>{
const body=document.body,nav=document.querySelector('.workspace-nav'),rail=document.querySelector('.satchy-rail');
nav.id='workspace-navigation';rail.id='workspace-assistant';
const content=document.querySelector('.workspace-content');content.tabIndex=0;content.setAttribute('aria-label','Workspace content');
const buttons={nav:document.getElementById('toggle-nav'),assistant:document.getElementById('toggle-assistant')};
function saved(key,fallback){try{const v=localStorage.getItem('terrasatch-panel-'+key);return v===null?fallback:v==='closed'}catch{return fallback}}
function set(key,closed,persist=true){body.classList.toggle(key+'-closed',closed);buttons[key].setAttribute('aria-expanded',String(!closed));if(persist)try{localStorage.setItem('terrasatch-panel-'+key,closed?'closed':'open')}catch{}}
for(const [key,panel] of [['nav',nav],['assistant',rail]]){const close=document.createElement('button');close.type='button';close.className='panel-close';close.textContent='Close';close.setAttribute('aria-label',key==='nav'?'Close navigation':'Close Satchy panel');panel.prepend(close);close.addEventListener('click',()=>{set(key,true);buttons[key].focus()});buttons[key].addEventListener('click',()=>{const closed=body.classList.contains(key+'-closed');set(key,!closed);if(closed)close.focus()});set(key,saved(key,key==='nav'?innerWidth<=700:innerWidth<=1100),false)}
window.addEventListener('hashchange',()=>{content.scrollTop=0;if(innerWidth<=700)set('nav',true,false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!body.classList.contains('assistant-closed')){set('assistant',true);buttons.assistant.focus()}else if(innerWidth<=700){set('nav',true);buttons.nav.focus()}}});
const status=document.getElementById('network-status');function online(){status.textContent=navigator.onLine?'Online':'Offline · reconnect to sync'}window.addEventListener('online',online);window.addEventListener('offline',online);online();
let installPrompt=null;const install=document.getElementById('install-workspace'),help=document.getElementById('install-help');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});install.addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else help.hidden=!help.hidden});document.getElementById('close-install-help').addEventListener('click',()=>help.hidden=true);window.addEventListener('appinstalled',()=>{install.hidden=true;help.hidden=true});if(matchMedia('(display-mode: standalone)').matches)install.hidden=true;
if('serviceWorker' in navigator)navigator.serviceWorker.register('/portal/service-worker.js',{scope:'/portal'}).catch(()=>{install.title='Use browser installation options; offline support is unavailable.'});
})();</script>'''
